export function getJutsu(id) {
  return JUTSUS[id] ?? null;
}

/** Lista de jutsus de um personagem (ignora ids inválidos). */
export function jutsusOf(character) {
  return (character.jutsu ?? []).map(getJutsu).filter(Boolean);
}
